-- Phase M review fixes: atomic, idempotent evidence and cancellation-safe completion.
CREATE OR REPLACE FUNCTION public.append_validation_cycle_if_running(p_run_id uuid,p_cycle_key text,p_close timestamptz,p_strategy jsonb,p_arbitration jsonb,p_exclusions jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE existing public.validation_cycles%ROWTYPE; BEGIN
 IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'; END IF;
 SELECT * INTO existing FROM public.validation_cycles WHERE run_id=p_run_id AND cycle_key=p_cycle_key;
 IF FOUND THEN IF existing.candle_close_time<>p_close OR existing.strategy_results<>p_strategy OR existing.arbitration<>p_arbitration OR existing.data_exclusions<>p_exclusions THEN RAISE EXCEPTION 'VALIDATION_EVIDENCE_CONFLICT'; END IF; RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.validation_runs WHERE id=p_run_id AND status='RUNNING' AND cancellation_requested_at IS NULL) THEN RAISE EXCEPTION 'VALIDATION_RUN_NOT_WRITABLE'; END IF;
 INSERT INTO public.validation_cycles(run_id,cycle_key,candle_close_time,strategy_results,arbitration,data_exclusions) VALUES(p_run_id,p_cycle_key,p_close,p_strategy,p_arbitration,p_exclusions);
 UPDATE public.validation_runs SET progress_completed=progress_completed+1,cumulative_progress=cumulative_progress+1 WHERE id=p_run_id AND status='RUNNING' AND cancellation_requested_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'VALIDATION_RUN_CANCELLED_DURING_APPEND'; END IF; RETURN true; END $$;
CREATE OR REPLACE FUNCTION public.complete_validation_run_if_current(p_run_id uuid,p_expected integer,p_summary jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'; END IF;
 IF (SELECT count(*) FROM public.validation_cycles WHERE run_id=p_run_id)<>p_expected THEN RAISE EXCEPTION 'VALIDATION_EVIDENCE_INCOMPLETE'; END IF;
 UPDATE public.validation_runs SET status='COMPLETED',outcome_metrics=p_summary,finished_at=now() WHERE id=p_run_id AND status='RUNNING' AND cancellation_requested_at IS NULL; RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.cancel_validation_run(p_run_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'; END IF; UPDATE public.validation_runs SET cancellation_requested_at=coalesce(cancellation_requested_at,now()),status='CANCELLED',finished_at=coalesce(finished_at,now()),lease_token=NULL,lease_owner=NULL,lease_expires_at=NULL WHERE id=p_run_id AND status IN('RUNNING','AWAITING_FEED'); RETURN FOUND; END $$;

CREATE OR REPLACE FUNCTION public.append_simulation_evidence_if_running(p_run_id uuid,p_sequence integer,p_evidence jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE old jsonb; BEGIN
 IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'; END IF; SELECT evidence INTO old FROM public.validation_simulation_evidence WHERE run_id=p_run_id AND sequence=p_sequence;
 IF FOUND THEN IF old<>p_evidence THEN RAISE EXCEPTION 'SIMULATION_EVIDENCE_CONFLICT'; END IF; RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.validation_simulation_runs WHERE id=p_run_id AND status='RUNNING' AND cancellation_requested_at IS NULL) THEN RAISE EXCEPTION 'SIMULATION_RUN_NOT_WRITABLE'; END IF;
 INSERT INTO public.validation_simulation_evidence(run_id,sequence,evidence) VALUES(p_run_id,p_sequence,p_evidence); RETURN true; END $$;
CREATE OR REPLACE FUNCTION public.complete_simulation_run_if_current(p_run_id uuid,p_expected integer,p_status text,p_summary jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'; END IF; IF p_status NOT IN('COMPLETED','BLOCKED','INCOMPLETE') THEN RAISE EXCEPTION 'INVALID_SIMULATION_COMPLETION'; END IF;
 IF (SELECT count(*) FROM public.validation_simulation_evidence WHERE run_id=p_run_id)<>p_expected THEN RAISE EXCEPTION 'SIMULATION_EVIDENCE_INCOMPLETE'; END IF;
 UPDATE public.validation_simulation_runs SET status=p_status,result_summary=p_summary,finished_at=now() WHERE id=p_run_id AND status='RUNNING' AND cancellation_requested_at IS NULL; RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.cancel_simulation_run(p_run_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'; END IF; UPDATE public.validation_simulation_runs SET cancellation_requested_at=coalesce(cancellation_requested_at,now()),status='CANCELLED',finished_at=coalesce(finished_at,now()) WHERE id=p_run_id AND status='RUNNING'; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.append_validation_cycle_if_running(uuid,text,timestamptz,jsonb,jsonb,jsonb),public.complete_validation_run_if_current(uuid,integer,jsonb),public.cancel_validation_run(uuid),public.append_simulation_evidence_if_running(uuid,integer,jsonb),public.complete_simulation_run_if_current(uuid,integer,text,jsonb),public.cancel_simulation_run(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.append_validation_cycle_if_running(uuid,text,timestamptz,jsonb,jsonb,jsonb),public.complete_validation_run_if_current(uuid,integer,jsonb),public.cancel_validation_run(uuid),public.append_simulation_evidence_if_running(uuid,integer,jsonb),public.complete_simulation_run_if_current(uuid,integer,text,jsonb),public.cancel_simulation_run(uuid) TO service_role;
